"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[8115],{3575(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>c,default:()=>u,frontMatter:()=>d,metadata:()=>o,toc:()=>p});const o=JSON.parse('{"id":"part3-agent-protocols/mcp-2025-update","title":"MCP Protocol Evolution: 2025 Foundations to the 2026 Stateless Core","description":"The earlier chapters establish MCP\'s durable mental model: a host contains clients, clients connect to servers, and servers expose tools, resources, and prompts. This chapter adds the version dimension. MCP changed su...","source":"@site/docs/part3-agent-protocols/04-mcp-2025-update.mdx","sourceDirName":"part3-agent-protocols","slug":"/part3-agent-protocols/04-mcp-2025-update","permalink":"/tutorials/part3-agent-protocols/04-mcp-2025-update","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":4,"frontMatter":{"title":"MCP Protocol Evolution: 2025 Foundations to the 2026 Stateless Core","slug":"/part3-agent-protocols/04-mcp-2025-update","description":"The earlier chapters establish MCP\'s durable mental model: a host contains clients, clients connect to servers, and servers expose tools, resources, and prompts. This chapter adds the version dimension. MCP changed su...","sidebar_label":"4. MCP protocol evolution","pagination_label":"4. MCP protocol evolution","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"3. MCP enterprise pattern","permalink":"/tutorials/part3-agent-protocols/03-mcp-enterprise-pattern"},"next":{"title":"5. A2A protocol 1.0","permalink":"/tutorials/part3-agent-protocols/05-a2a-protocol"}}');var r=n(4848),s=n(8453),i=n(8172);const a=JSON.parse('{"sourcePath":"part3-agent-protocols/04-mcp-2025-update.html","route":"/part3-agent-protocols/04-mcp-2025-update","kind":"chapter","partId":"part3","partLabel":"Part III - Agent Protocols & Integration","accent":"violet","heading":"MCP Protocol Evolution: 2025 Foundations to the 2026 Stateless Core","title":"MCP Protocol Evolution: 2025 Foundations to the 2026 Stateless Core","description":"The earlier chapters establish MCP\'s durable mental model: a host contains clients, clients connect to servers, and servers expose tools, resources, and prompts. This chapter adds the version dimension. MCP changed su...","readingMinutes":9,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-what-stays-stable-across-versions","label":"1) What stays stable across versions"},{"id":"2-the-two-protocol-eras","label":"2) The two protocol eras"},{"id":"3-the-current-stateless-request-model","label":"3) The current stateless request model"},{"id":"4-transport-evolution-http-sse-to-streamable-http","label":"4) Transport evolution: HTTP+SSE to Streamable HTTP"},{"id":"5-authorization-protected-resources-and-least-privilege","label":"5) Authorization: protected resources and least privilege"},{"id":"6-from-elicitation-to-multi-round-trip-requests","label":"6) From elicitation to multi-round-trip requests"},{"id":"7-structured-tool-output","label":"7) Structured tool output"},{"id":"8-resource-links-keep-large-data-out-of-the-immediate-context","label":"8) Resource links keep large data out of the immediate context"},{"id":"9-operational-changes-worth-remembering","label":"9) Operational changes worth remembering"},{"id":"10-migration-checklist","label":"10) Migration checklist"},{"id":"official-references","label":"Official references"}],"html":"<div class=\\"ch\\">\\n\\n\\n\\n<p>\\n  The earlier chapters establish MCP\'s durable mental model: a host contains\\n  clients, clients connect to servers, and servers expose\\n  <strong>tools</strong>, <strong>resources</strong>, and\\n  <strong>prompts</strong>. This chapter adds the version dimension. MCP\\n  changed substantially during 2025 and again in the\\n  <code>2026-07-28</code> specification. The capability model remains\\n  recognizable, but connection state, discovery, subscriptions, server\\n  requests, tasks, and registration changed.\\n</p>\\n\\n<div class=\\"tr-warn\\">\\n  <strong>Read the version before copying a wire example.</strong>\\n  The 2025 session-based protocol and the 2026 stateless protocol are both\\n  explained because existing systems may still implement either one. A\\n  production client should negotiate or explicitly select the protocol\\n  version; it should never combine fields from the two eras.\\n</div>\\n\\n<figure class=\\"figure-card\\">\\n  <svg viewBox=\\"0 0 1040 350\\" role=\\"img\\" aria-labelledby=\\"mcp-evolution-title mcp-evolution-desc\\">\\n    <title id=\\"mcp-evolution-title\\">MCP evolution from two-endpoint HTTP to stateless requests</title>\\n    <desc id=\\"mcp-evolution-desc\\">A timeline showing HTTP plus SSE, 2025 Streamable HTTP with sessions, and the 2026 stateless protocol.</desc>\\n    <defs>\\n      <marker id=\\"mcp-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"5\\" orient=\\"auto\\">\\n        <path d=\\"M0,0 L10,5 L0,10 Z\\" fill=\\"#1769e0\\"></path>\\n      </marker>\\n      <linearGradient id=\\"mcp-current\\" x1=\\"0\\" x2=\\"1\\">\\n        <stop offset=\\"0\\" stop-color=\\"#e8f2ff\\"></stop>\\n        <stop offset=\\"1\\" stop-color=\\"#e9fbf2\\"></stop>\\n      </linearGradient>\\n    </defs>\\n\\n    <text x=\\"60\\" y=\\"45\\" font-size=\\"18\\" font-weight=\\"700\\" fill=\\"#162033\\">Early HTTP transport</text>\\n    <rect x=\\"45\\" y=\\"70\\" width=\\"250\\" height=\\"205\\" rx=\\"14\\" fill=\\"#fff4e5\\" stroke=\\"#d78b00\\" stroke-width=\\"2\\"></rect>\\n    <rect x=\\"75\\" y=\\"105\\" width=\\"190\\" height=\\"46\\" rx=\\"9\\" fill=\\"#ffffff\\" stroke=\\"#d78b00\\"></rect>\\n    <text x=\\"170\\" y=\\"134\\" text-anchor=\\"middle\\" font-size=\\"16\\" fill=\\"#162033\\">POST /messages</text>\\n    <rect x=\\"75\\" y=\\"172\\" width=\\"190\\" height=\\"46\\" rx=\\"9\\" fill=\\"#ffffff\\" stroke=\\"#d78b00\\"></rect>\\n    <text x=\\"170\\" y=\\"201\\" text-anchor=\\"middle\\" font-size=\\"16\\" fill=\\"#162033\\">GET /sse</text>\\n    <text x=\\"170\\" y=\\"248\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#6b4a00\\">two coordinated endpoints</text>\\n\\n    <line x1=\\"310\\" y1=\\"173\\" x2=\\"370\\" y2=\\"173\\" stroke=\\"#1769e0\\" stroke-width=\\"4\\" marker-end=\\"url(#mcp-arrow)\\"></line>\\n\\n    <text x=\\"390\\" y=\\"45\\" font-size=\\"18\\" font-weight=\\"700\\" fill=\\"#162033\\">2025 foundation</text>\\n    <rect x=\\"375\\" y=\\"70\\" width=\\"285\\" height=\\"205\\" rx=\\"14\\" fill=\\"#f1ecff\\" stroke=\\"#7548d8\\" stroke-width=\\"2\\"></rect>\\n    <rect x=\\"412\\" y=\\"105\\" width=\\"210\\" height=\\"46\\" rx=\\"9\\" fill=\\"#ffffff\\" stroke=\\"#7548d8\\"></rect>\\n    <text x=\\"517\\" y=\\"134\\" text-anchor=\\"middle\\" font-size=\\"16\\" fill=\\"#162033\\">POST or GET /mcp</text>\\n    <rect x=\\"412\\" y=\\"172\\" width=\\"210\\" height=\\"46\\" rx=\\"9\\" fill=\\"#ffffff\\" stroke=\\"#7548d8\\"></rect>\\n    <text x=\\"517\\" y=\\"201\\" text-anchor=\\"middle\\" font-size=\\"16\\" fill=\\"#162033\\">initialize + session ID</text>\\n    <text x=\\"517\\" y=\\"248\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#54349a\\">Streamable HTTP</text>\\n\\n    <line x1=\\"675\\" y1=\\"173\\" x2=\\"735\\" y2=\\"173\\" stroke=\\"#1769e0\\" stroke-width=\\"4\\" marker-end=\\"url(#mcp-arrow)\\"></line>\\n\\n    <text x=\\"755\\" y=\\"45\\" font-size=\\"18\\" font-weight=\\"700\\" fill=\\"#162033\\">2026 current core</text>\\n    <rect x=\\"740\\" y=\\"70\\" width=\\"255\\" height=\\"205\\" rx=\\"14\\" fill=\\"url(#mcp-current)\\" stroke=\\"#14875a\\" stroke-width=\\"2.5\\"></rect>\\n    <rect x=\\"775\\" y=\\"102\\" width=\\"185\\" height=\\"42\\" rx=\\"9\\" fill=\\"#ffffff\\" stroke=\\"#1769e0\\"></rect>\\n    <text x=\\"867\\" y=\\"128\\" text-anchor=\\"middle\\" font-size=\\"15\\" fill=\\"#162033\\">server/discover</text>\\n    <rect x=\\"775\\" y=\\"158\\" width=\\"185\\" height=\\"42\\" rx=\\"9\\" fill=\\"#ffffff\\" stroke=\\"#14875a\\"></rect>\\n    <text x=\\"867\\" y=\\"184\\" text-anchor=\\"middle\\" font-size=\\"15\\" fill=\\"#162033\\">self-contained request</text>\\n    <rect x=\\"775\\" y=\\"214\\" width=\\"185\\" height=\\"42\\" rx=\\"9\\" fill=\\"#ffffff\\" stroke=\\"#d78b00\\"></rect>\\n    <text x=\\"867\\" y=\\"240\\" text-anchor=\\"middle\\" font-size=\\"15\\" fill=\\"#162033\\">explicit state handles</text>\\n\\n    <text x=\\"520\\" y=\\"322\\" text-anchor=\\"middle\\" font-size=\\"16\\" font-weight=\\"700\\" fill=\\"#162033\\">\\n      Stable concepts: JSON-RPC, tools, resources, prompts, consent, and authorization\\n    </text>\\n  </svg>\\n  <figcaption>\\n    MCP kept its capability model while moving transport and conversational\\n    context out of implicit connection state.\\n  </figcaption>\\n</figure>\\n\\n<h2 id=\\"1-what-stays-stable-across-versions\\">1) What stays stable across versions</h2>\\n\\n<p>\\n  MCP standardizes how an AI application discovers and invokes external\\n  capabilities. All versions in this chapter use JSON-RPC 2.0 messages and\\n  preserve three server-facing primitives:\\n</p>\\n\\n<table>\\n  <thead>\\n    <tr><th>Primitive</th><th>Purpose</th><th>Typical example</th></tr>\\n  </thead>\\n  <tbody>\\n    <tr>\\n      <td><strong>Tool</strong></td>\\n      <td>Perform an operation with typed arguments.</td>\\n      <td><code>orders/create</code> or <code>weather/get</code></td>\\n    </tr>\\n    <tr>\\n      <td><strong>Resource</strong></td>\\n      <td>Expose addressable context that can be read on demand.</td>\\n      <td><code>doc://contracts/acme-msa</code></td>\\n    </tr>\\n    <tr>\\n      <td><strong>Prompt</strong></td>\\n      <td>Publish a reusable, parameterized message template or workflow.</td>\\n      <td>A code-review or incident-triage prompt</td>\\n    </tr>\\n  </tbody>\\n</table>\\n\\n<p>\\n  The host still owns the trust decision. A tool description is not proof\\n  that the tool is safe; the host must authenticate the server, constrain\\n  what can be called, validate arguments, obtain appropriate user consent,\\n  and render results as untrusted content.\\n</p>\\n\\n<h2 id=\\"2-the-two-protocol-eras\\">2) The two protocol eras</h2>\\n\\n<table>\\n  <thead>\\n    <tr><th>Concern</th><th>2025 protocol family</th><th><code>2026-07-28</code> core</th></tr>\\n  </thead>\\n  <tbody>\\n    <tr>\\n      <td>Context</td>\\n      <td>Negotiated during <code>initialize</code>; optionally tied to <code>Mcp-Session-Id</code>.</td>\\n      <td>Every request is self-contained; protocol version and capabilities travel in <code>_meta</code>.</td>\\n    </tr>\\n    <tr>\\n      <td>Discovery</td>\\n      <td>Initialization and feature-specific list calls.</td>\\n      <td><code>server/discover</code> advertises versions, capabilities, and server identity.</td>\\n    </tr>\\n    <tr>\\n      <td>Server notifications</td>\\n      <td>A transport-level GET stream and resource subscribe/unsubscribe calls.</td>\\n      <td><code>subscriptions/listen</code> is an explicit long-lived request.</td>\\n    </tr>\\n    <tr>\\n      <td>More client input</td>\\n      <td>Server-initiated requests such as <code>elicitation/create</code>.</td>\\n      <td>An <code>input_required</code> result asks the client to retry with input responses.</td>\\n    </tr>\\n    <tr>\\n      <td>Long-running tasks</td>\\n      <td>Introduced experimentally in the core.</td>\\n      <td>Moved to the official <code>io.modelcontextprotocol/tasks</code> extension.</td>\\n    </tr>\\n  </tbody>\\n</table>\\n\\n<div class=\\"tr-note\\">\\n  <strong>Compatibility rule</strong>\\n  The 2025 sections below are not disposable history. They explain why\\n  Streamable HTTP, protected-resource metadata, structured output, and\\n  resource links exist. When implementing, however, use the message shapes\\n  for the version your client and server actually select.\\n</div>\\n\\n<h2 id=\\"3-the-current-stateless-request-model\\">3) The current stateless request model</h2>\\n\\n<h3 id=\\"3-1-discovery-replaces-the-mandatory-handshake\\">3.1 Discovery replaces the mandatory handshake</h3>\\n\\n<p>\\n  In the current protocol, a server must implement\\n  <code>server/discover</code>. A client may call it before other methods to\\n  choose a supported version and inspect capabilities, or it may optimistically\\n  send another request and handle an unsupported-version error.\\n</p>\\n\\n<pre><code class=\\"language-json\\">{\\n  \\"jsonrpc\\": \\"2.0\\",\\n  \\"id\\": \\"discover-1\\",\\n  \\"method\\": \\"server/discover\\",\\n  \\"params\\": {\\n    \\"_meta\\": {\\n      \\"io.modelcontextprotocol/protocolVersion\\": \\"2026-07-28\\",\\n      \\"io.modelcontextprotocol/clientInfo\\": {\\n        \\"name\\": \\"book-example-host\\",\\n        \\"version\\": \\"1.0.0\\"\\n      },\\n      \\"io.modelcontextprotocol/clientCapabilities\\": {}\\n    }\\n  }\\n}</code></pre>\\n\\n<p>\\n  A successful result includes <code>resultType: \\"complete\\"</code>, supported\\n  protocol versions, server capabilities, server identity metadata, and cache\\n  hints. Discovery is useful for up-front negotiation, but it does not create\\n  a session.\\n</p>\\n\\n<h3 id=\\"3-2-every-request-carries-its-own-protocol-context\\">3.2 Every request carries its own protocol context</h3>\\n\\n<pre><code class=\\"language-json\\">{\\n  \\"jsonrpc\\": \\"2.0\\",\\n  \\"id\\": 42,\\n  \\"method\\": \\"tools/call\\",\\n  \\"params\\": {\\n    \\"name\\": \\"quote\\",\\n    \\"arguments\\": {\\"symbol\\": \\"ACME\\"},\\n    \\"_meta\\": {\\n      \\"io.modelcontextprotocol/protocolVersion\\": \\"2026-07-28\\",\\n      \\"io.modelcontextprotocol/clientCapabilities\\": {},\\n      \\"io.modelcontextprotocol/clientInfo\\": {\\n        \\"name\\": \\"book-example-host\\",\\n        \\"version\\": \\"1.0.0\\"\\n      }\\n    }\\n  }\\n}</code></pre>\\n\\n<p>\\n  The server must be able to process this request without remembering an\\n  earlier initialize call, connection, conversation, or process. If an\\n  application needs state across calls, the server returns an explicit\\n  identifier, such as <code>task_7f12</code> or\\n  <code>checkout_session_91</code>, and the client passes that handle in later\\n  arguments.\\n</p>\\n\\n<div class=\\"tr-tip\\">\\n  <strong>Why statelessness matters</strong>\\n  Any healthy instance can process the next request. Load balancers no longer\\n  need sticky sessions, a reconnect does not erase hidden protocol state, and\\n  task or conversation identity is visible in application data rather than\\n  inferred from a socket.\\n</div>\\n\\n<h3 id=\\"3-3-result-types-make-continuation-explicit\\">3.3 Result types make continuation explicit</h3>\\n\\n<p>\\n  Every current result has a <code>resultType</code>. Ordinary final responses\\n  use <code>\\"complete\\"</code>. A response that needs more information uses\\n  <code>\\"input_required\\"</code>. Clients talking to an older server treat a\\n  missing <code>resultType</code> as <code>\\"complete\\"</code> for backward\\n  compatibility.\\n</p>\\n\\n<h2 id=\\"4-transport-evolution-http-sse-to-streamable-http\\">4) Transport evolution: HTTP+SSE to Streamable HTTP</h2>\\n\\n<h3 id=\\"4-1-before-streamable-http\\">4.1 Before Streamable HTTP</h3>\\n\\n<p>\\n  Early remote MCP examples exposed two coordinated endpoints:\\n  <code>POST /messages</code> carried client-to-server requests and\\n  <code>GET /sse</code> held a Server-Sent Events channel for\\n  server-to-client messages. Deployments had to coordinate two endpoints,\\n  preserve connection affinity, and survive load-balancer idle timeouts.\\n</p>\\n\\n<h3 id=\\"4-2-the-2025-streamable-http-model\\">4.2 The 2025 Streamable HTTP model</h3>\\n\\n<p>\\n  The <code>2025-03-26</code> family introduced one endpoint, commonly\\n  <code>/mcp</code>:\\n</p>\\n\\n<ul>\\n  <li>\\n    <strong><code>POST /mcp</code></strong> accepted a JSON-RPC request and\\n    returned either one JSON response or an SSE response stream containing\\n    the result and request-scoped progress.\\n  </li>\\n  <li>\\n    <strong><code>GET /mcp</code></strong> could open an independent SSE stream\\n    for notifications such as resource changes, sampling, or elicitation.\\n  </li>\\n  <li>\\n    The initialize response could issue <code>Mcp-Session-Id</code>, and later\\n    requests sent the negotiated <code>MCP-Protocol-Version</code>.\\n  </li>\\n</ul>\\n\\n<p>\\n  This was a major improvement over the two-endpoint HTTP+SSE transport, and\\n  many deployed clients still use it. It is also the context in which calls\\n  such as <code>mcp.run(transport=\\"streamable-http\\")</code> first appeared in\\n  SDK examples.\\n</p>\\n\\n<h3 id=\\"4-3-the-2026-streamable-http-model\\">4.3 The 2026 Streamable HTTP model</h3>\\n\\n<p>\\n  Streamable HTTP remains, but the protocol-level session and GET notification\\n  stream do not. The current model uses:\\n</p>\\n\\n<ul>\\n  <li>self-contained <code>POST</code> requests with required protocol metadata;</li>\\n  <li>the <code>Mcp-Method</code> and <code>Mcp-Name</code> request headers for HTTP routing consistency;</li>\\n  <li>request-scoped response streams for progress and log notifications;</li>\\n  <li><code>subscriptions/listen</code> when a client explicitly wants selected change notifications;</li>\\n  <li>a new request ID when retrying after a broken in-flight response stream.</li>\\n</ul>\\n\\n<div class=\\"tr-warn\\">\\n  <strong>HTTP boundary security</strong>\\n  Validate the <code>Origin</code> header to defend against DNS rebinding,\\n  bind local-only servers to loopback, require HTTPS and authentication for\\n  remote servers, and never treat CORS as authorization.\\n</div>\\n\\n<h2 id=\\"5-authorization-protected-resources-and-least-privilege\\">5) Authorization: protected resources and least privilege</h2>\\n\\n<p>\\n  A simple bearer-token middleware is useful for learning. Production remote\\n  MCP uses the protocol\'s OAuth profile and the same resource-server\\n  principles developed in Part II:\\n</p>\\n\\n<ol>\\n  <li>\\n    The MCP server is the <strong>protected resource</strong>. Its\\n    <code>/.well-known/oauth-protected-resource</code> metadata identifies\\n    trusted authorization servers.\\n  </li>\\n  <li>\\n    Public clients use Authorization Code with PKCE. OAuth 2.1 remains an\\n    Internet-Draft, so treat \\"OAuth 2.1\\" as a modern profile: follow the\\n    current OAuth security best practices and avoid implicit and password\\n    grants.\\n  </li>\\n  <li>\\n    The client includes a resource indicator so the access token is minted\\n    for this MCP resource rather than silently replayed at another server.\\n  </li>\\n  <li>\\n    The server validates JWTs with issuer metadata and JWKS, or validates\\n    opaque tokens through introspection. It checks issuer, audience/resource,\\n    expiry, and required scopes.\\n  </li>\\n  <li>\\n    Authorization-server issuer binding matters: credentials issued by one\\n    authorization server must not be reused at another.\\n  </li>\\n</ol>\\n\\n<p>\\n  The 2025 guidance used Dynamic Client Registration (RFC 7591) for clients\\n  unknown to the authorization server. In the current specification it is\\n  deprecated in favor of <strong>Client ID Metadata Documents</strong>,\\n  although DCR remains a compatibility path for authorization servers that\\n  do not yet support the replacement.\\n</p>\\n\\n<div class=\\"tr-tip\\">\\n  <strong>End-user versus workload identity</strong>\\n  DPoP can sender-constrain a public-client token; mTLS is common between\\n  workloads; token exchange is the cleanest way for a host to obtain a\\n  downstream token that represents an authorized user delegation. Do not\\n  forward an upstream access token merely because both services accept JWTs.\\n</div>\\n\\n<h2 id=\\"6-from-elicitation-to-multi-round-trip-requests\\">6) From elicitation to multi-round-trip requests</h2>\\n\\n<h3 id=\\"6-1-the-2025-elicitation-model\\">6.1 The 2025 elicitation model</h3>\\n\\n<p>\\n  A tool sometimes needs a missing parameter, clarification, or confirmation.\\n  The 2025 protocol introduced <code>elicitation/create</code>, a\\n  server-initiated request routed through the host to the user:\\n</p>\\n\\n<pre><code class=\\"language-python\\"># Historical 2025-style conceptual FastMCP API\\n@mcp.tool()\\nasync def book_flight(ctx, origin: str, destination: str) -&gt; dict:\\n    if not origin:\\n        response = await ctx.elicit(\\n            message=\\"Which city should I book the flight from?\\",\\n            schema={\\n                \\"type\\": \\"object\\",\\n                \\"properties\\": {\\"origin\\": {\\"type\\": \\"string\\"}},\\n                \\"required\\": [\\"origin\\"],\\n            },\\n        )\\n        if response.action != \\"accept\\":\\n            return {\\"error\\": \\"user_declined\\"}\\n        origin = response.content[\\"origin\\"]\\n    return await reserve(origin, destination)</code></pre>\\n\\n<p>\\n  The host displayed the prompt, validated the structured response, and\\n  returned an <code>accept</code>, <code>decline</code>, or\\n  <code>cancel</code> outcome. This established a clean human-in-the-loop\\n  contract for sensitive tools.\\n</p>\\n\\n<h3 id=\\"6-2-the-2026-mrtr-model\\">6.2 The 2026 MRTR model</h3>\\n\\n<p>\\n  The current protocol removes server-initiated requests from the core\\n  transport. Instead, the server returns an\\n  <code>InputRequiredResult</code>. Its <code>inputRequests</code> describe\\n  the required elicitation, sampling, or roots input. The client gathers the\\n  information and retries the original method with\\n  <code>inputResponses</code>.\\n</p>\\n\\n<pre><code class=\\"language-json\\">{\\n  \\"jsonrpc\\": \\"2.0\\",\\n  \\"id\\": 42,\\n  \\"result\\": {\\n    \\"resultType\\": \\"input_required\\",\\n    \\"inputRequests\\": [\\n      {\\n        \\"requestId\\": \\"origin-city\\",\\n        \\"type\\": \\"elicitation\\",\\n        \\"message\\": \\"Which city should I book the flight from?\\"\\n      }\\n    ]\\n  }\\n}</code></pre>\\n\\n<p>\\n  The exact schema should come from the selected SDK and protocol version.\\n  The important mental shift is that the server does not call backward over\\n  an assumed session: it returns a continuation requirement, and the client\\n  explicitly resumes the operation.\\n</p>\\n\\n<h2 id=\\"7-structured-tool-output\\">7) Structured tool output</h2>\\n\\n<p>\\n  Plain text is useful for a human, but fragile for application code.\\n  Structured output lets a tool declare a JSON Schema and return machine-ready\\n  data in <code>structuredContent</code>, optionally alongside a readable\\n  content rendering:\\n</p>\\n\\n<pre><code class=\\"language-python\\">@mcp.tool(\\n    output_schema={\\n        \\"type\\": \\"object\\",\\n        \\"properties\\": {\\n            \\"price\\": {\\"type\\": \\"number\\"},\\n            \\"currency\\": {\\"type\\": \\"string\\"},\\n        },\\n        \\"required\\": [\\"price\\", \\"currency\\"],\\n        \\"additionalProperties\\": False,\\n    },\\n)\\ndef quote(symbol: str) -&gt; dict:\\n    return {\\"price\\": 142.55, \\"currency\\": \\"USD\\"}</code></pre>\\n\\n<p>\\n  The host can render the result as a chart, badge, form, or JSON view without\\n  asking the language model to re-parse prose. Current MCP accepts JSON Schema\\n  2020-12 by default and permits a full JSON value in\\n  <code>structuredContent</code>. Validators should bound schema depth and\\n  composition complexity, and they must not automatically fetch arbitrary\\n  network <code>$ref</code> targets.\\n</p>\\n\\n<h2 id=\\"8-resource-links-keep-large-data-out-of-the-immediate-context\\">8) Resource links keep large data out of the immediate context</h2>\\n\\n<p>\\n  A search result, PDF, or table dump can consume the model\'s context before\\n  the model knows whether it is relevant. A tool can return a typed resource\\n  link instead:\\n</p>\\n\\n<pre><code class=\\"language-json\\">{\\n  \\"content\\": [\\n    {\\n      \\"type\\": \\"text\\",\\n      \\"text\\": \\"I found three matching contracts.\\"\\n    },\\n    {\\n      \\"type\\": \\"resource_link\\",\\n      \\"uri\\": \\"doc://contracts/2024-Q4/acme-msa.pdf\\",\\n      \\"mimeType\\": \\"application/pdf\\",\\n      \\"name\\": \\"Acme MSA (2024-Q4)\\"\\n    }\\n  ]\\n}</code></pre>\\n\\n<p>\\n  The model receives a compact handle. The host can fetch the referenced\\n  resource with <code>resources/read</code> only when needed and only after\\n  applying authorization and size limits. A URI is a reference, not evidence\\n  that the target is safe: defend against SSRF, disallowed schemes, oversized\\n  content, and cross-tenant access.\\n</p>\\n\\n<h2 id=\\"9-operational-changes-worth-remembering\\">9) Operational changes worth remembering</h2>\\n\\n<table>\\n  <thead>\\n    <tr><th>Feature</th><th>Current guidance</th><th>Reason</th></tr>\\n  </thead>\\n  <tbody>\\n    <tr>\\n      <td>JSON-RPC batching</td>\\n      <td>Use one request per call; batching was removed in <code>2025-06-18</code>.</td>\\n      <td>Clear request lifecycle and streaming semantics.</td>\\n    </tr>\\n    <tr>\\n      <td>Progress</td>\\n      <td>Keep request-scoped progress on that request\'s response stream.</td>\\n      <td>Avoid cross-request ambiguity.</td>\\n    </tr>\\n    <tr>\\n      <td>Change notifications</td>\\n      <td>Use <code>subscriptions/listen</code> and opt into specific notification types.</td>\\n      <td>Subscriptions become explicit request state.</td>\\n    </tr>\\n    <tr>\\n      <td>Tasks</td>\\n      <td>Use the official tasks extension, with <code>tasks/get</code> polling and <code>tasks/update</code> for later input.</td>\\n      <td>Durable work evolves independently of the core.</td>\\n    </tr>\\n    <tr>\\n      <td>Roots, sampling, logging</td>\\n      <td>Existing implementations may support them, but new implementations should follow the documented migration paths because these features are deprecated.</td>\\n      <td>Reduce connection-coupled client features.</td>\\n    </tr>\\n    <tr>\\n      <td>Tool annotations</td>\\n      <td>Treat read-only, destructive, idempotent, and open-world hints as untrusted metadata.</td>\\n      <td>The host still enforces policy and consent.</td>\\n    </tr>\\n    <tr>\\n      <td>Caching</td>\\n      <td>Honor <code>ttlMs</code> and <code>cacheScope</code> on cacheable list/read results.</td>\\n      <td>Reduce polling without leaking private results through shared caches.</td>\\n    </tr>\\n    <tr>\\n      <td>Tracing</td>\\n      <td>Propagate <code>traceparent</code>, <code>tracestate</code>, and <code>baggage</code> in <code>_meta</code>.</td>\\n      <td>Trace one operation across host, server, and downstream systems.</td>\\n    </tr>\\n  </tbody>\\n</table>\\n\\n<h2 id=\\"10-migration-checklist\\">10) Migration checklist</h2>\\n\\n<table>\\n  <thead>\\n    <tr><th>Older design</th><th>2025 improvement</th><th>Current destination</th></tr>\\n  </thead>\\n  <tbody>\\n    <tr>\\n      <td><code>/messages</code> plus <code>/sse</code></td>\\n      <td>One Streamable HTTP <code>/mcp</code> endpoint</td>\\n      <td>Keep Streamable HTTP, remove the independent GET stream, and use <code>subscriptions/listen</code>.</td>\\n    </tr>\\n    <tr>\\n      <td>Implicit connection assumptions</td>\\n      <td><code>initialize</code> plus optional <code>Mcp-Session-Id</code></td>\\n      <td>Per-request version and capabilities in <code>_meta</code>; explicit application handles.</td>\\n    </tr>\\n    <tr>\\n      <td>Ad hoc feature detection</td>\\n      <td>Initialization capabilities</td>\\n      <td><code>server/discover</code> plus per-request capability declaration.</td>\\n    </tr>\\n    <tr>\\n      <td>Custom bearer authentication</td>\\n      <td>Protected Resource Metadata, PKCE, and resource indicators</td>\\n      <td>Retain the resource-server model; prefer Client ID Metadata Documents over new DCR integrations.</td>\\n    </tr>\\n    <tr>\\n      <td>Plain-text-only tool result</td>\\n      <td>Output schema and <code>structuredContent</code></td>\\n      <td>Use JSON Schema 2020-12 and bounded validation.</td>\\n    </tr>\\n    <tr>\\n      <td>Inline large blobs</td>\\n      <td><code>resource_link</code></td>\\n      <td>Keep links compact and fetch with authorization and network-safety controls.</td>\\n    </tr>\\n    <tr>\\n      <td>Fail when information is missing</td>\\n      <td><code>elicitation/create</code></td>\\n      <td>Return <code>input_required</code> and resume through MRTR.</td>\\n    </tr>\\n  </tbody>\\n</table>\\n\\n<div class=\\"tr-note\\">\\n  <strong>Chapter transition</strong>\\n  The next chapter moves from connecting one host to capabilities toward\\n  collaboration between autonomous agents. MCP and A2A overlap at the system\\n  boundary, but they solve different primary problems: MCP exposes context\\n  and operations; A2A delegates stateful work to another agent.\\n</div>\\n\\n<h2 id=\\"official-references\\">Official references</h2>\\n<ul>\\n  <li><a href=\\"https://modelcontextprotocol.io/specification/2026-07-28\\">MCP <code>2026-07-28</code> specification</a></li>\\n  <li><a href=\\"https://modelcontextprotocol.io/specification/2026-07-28/changelog\\">MCP <code>2026-07-28</code> key changes</a></li>\\n  <li><a href=\\"https://modelcontextprotocol.io/specification/2026-07-28/server/discover\\"><code>server/discover</code> reference</a></li>\\n</ul>\\n\\n</div>"}'),d={title:"MCP Protocol Evolution: 2025 Foundations to the 2026 Stateless Core",slug:"/part3-agent-protocols/04-mcp-2025-update",description:"The earlier chapters establish MCP's durable mental model: a host contains clients, clients connect to servers, and servers expose tools, resources, and prompts. This chapter adds the version dimension. MCP changed su...",sidebar_label:"4. MCP protocol evolution",pagination_label:"4. MCP protocol evolution",hide_title:!0,hide_table_of_contents:!0},c=void 0,l={},p=[];function h(e){return(0,r.jsx)(i.A,{content:a})}function u(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(h,{...e})}):h()}}}]);